const categoryStockSummary = (list=products) => {const totals={};list.forEach(product=>{const category=product.category||'Uncategorized',stock=Number(product.stock)||0;totals[category]??={pieces:0,value:0};totals[category].pieces+=stock;totals[category].value+=stock*(Number(product.price)||0)});return `<div class="category-stock-summary"><div class="category-summary-title">Category-wise stock</div><div class="category-summary-grid">${Object.entries(totals).sort((a,b)=>a[0].localeCompare(b[0])).map(([category,total])=>`<button class="category-summary-item" type="button" data-category="${category}"><b class="category-summary-name">${category}</b><small class="category-summary-pieces">${total.pieces.toLocaleString()} pcs</small><strong>${money(total.value)}</strong></button>`).join('')||'<div class="empty">No category stock available</div>'}</div></div>`;};
