save = function(){ originalSave(); persistPriceHistory(); const critical=products.filter(p=>p.stock<=0||p.stock<=p.min); const key=critical.map(p=>`${p.id}:${p.stock}`).join('|'); if(key&&key!==lastAlertKey){lastAlertKey=key;notifyTelegram(`Godown Alert\n${critical.some(p=>p.stock<=0)?'Out of stock / ':''}Low stock items\n${critical.map(p=>`${p.name}: ${p.stock} pcs (alert ${p.min})`).join('\n')}`);} };
reports=function(){const r=reportRows(),purchaseQty=r.purchases.reduce((s,a)=>s+(Number(a.qty)||0),0),salesQty=r.sales.reduce((s,a)=>s+(Number(a.qty)||0),0),purchaseValue=r.purchases.reduce((s,a)=>s+(Number(a.qty)||0)*(Number(a.transactionPrice??a.price)||0),0),salesValue=r.sales.reduce((s,a)=>s+(Number(a.qty)||0)*(Number(a.transactionPrice??a.price)||0),0),stockValue=products.reduce((s,p)=>s+(Number(p.stock)||0)*(Number(p.price)||0),0),salesByProduct={};r.sales.forEach(a=>{const key=a.product||'Unknown product';if(!salesByProduct[key])salesByProduct[key]={qty:0,value:0};salesByProduct[key].qty+=Number(a.qty)||0;salesByProduct[key].value+=(Number(a.qty)||0)*(Number(a.transactionPrice??a.price)||0)});const list=(items,field)=>items.slice(0,5).map(p=>`<div class="bar-row"><div class="bar-label"><span>${p.name}</span><b>${field(p)}</b></div></div>`).join('')||'<div class="empty">No data</div>',salesList=Object.entries(salesByProduct).sort((a,b)=>b[1].qty-a[1].qty).slice(0,10).map(([name,data])=>`<div class="bar-row"><div class="bar-label"><span>${name}</span><b>${data.qty} pcs · ${money(data.value)}</b></div></div>`).join('')||'<div class="empty">No sales yet</div>';return `<section class="main-view"><div class="view-head"><div><div class="eyebrow">INSIGHTS · COMPLETE STOCK REPORT</div><h2>Reports</h2></div><div><button class="primary-button" id="export-report">Export CSV <span>↓</span></button> <button class="primary-button" id="export-pdf">Print / PDF</button> <button class="primary-button" id="telegram-summary">Telegram closing summary</button></div></div><div class="metric-grid"><div class="metric-card"><p>STOCK IN</p><strong>${purchaseQty.toLocaleString()}</strong><small>${money(purchaseValue)}</small></div><div class="metric-card"><p>SALES</p><strong>${salesQty.toLocaleString()}</strong><small>${money(salesValue)}</small></div><div class="metric-card"><p>STOCK VALUE</p><strong>${money(stockValue)}</strong><small>Current godown stock value</small></div><div class="metric-card"><p>LOW / OUT</p><strong>${r.low.length} / ${r.out.length}</strong><small>Needs attention</small></div></div><div class="report-grid"><div class="report-card"><h3>Category-wise stock</h3>${Object.entries(r.byCategory).map(([key,value])=>`<div class="bar-row"><div class="bar-label"><span>${key}</span><b>${value} pcs</b></div></div>`).join('')||'<div class="empty">No data</div>'}</div><div class="report-card"><h3>Supplier-wise stock</h3>${Object.entries(r.bySupplier).map(([key,value])=>`<div class="bar-row"><div class="bar-label"><span>${key}</span><b>${value} pcs</b></div></div>`).join('')||'<div class="empty">No data</div>'}</div><div class="report-card"><h3>Sales-wise stock out</h3>${salesList}</div><div class="report-card"><h3>Fast-moving products</h3>${list(r.fast,p=>`${activity.filter(a=>a.product===p.name&&a.type==='out').reduce((s,a)=>s+(a.qty||0),0)} pcs sold`)}</div><div class="report-card"><h3>Slow-moving products</h3>${list(r.slow,p=>`${activity.filter(a=>a.product===p.name&&a.type==='out').length} sales`)}</div><div class="report-card"><h3>Dead stock</h3>${list(r.dead,p=>`${p.stock} pcs`)}</div><div class="report-card"><h3>Price change history</h3>${priceHistory.slice(0,8).map(h=>`<div class="bar-row"><div class="bar-label"><span>${h.product}</span><b>${money(h.oldPrice)} → ${money(h.newPrice)}</b></div></div>`).join('')||'<div class="empty">No price changes yet</div>'}</div></div></section>`};
