const recordPriceChange = (product, oldPrice, newPrice, reason='Product edit') => { if (Number(oldPrice) === Number(newPrice)) return; const entry = { id: Date.now() + Math.random(), productId: product.id, product: product.name, category: product.category, code: product.code, variant: product.variant, oldPrice: Number(oldPrice)||0, newPrice: Number(newPrice)||0, changedBy: currentRole === 'admin' ? 'Owner' : 'Entry Staff', changedAt: new Date().toISOString(), reason }; priceHistory.unshift(entry); return entry; };
const reportRows = () => { const purchases=activity.filter(a=>a.type==='in'), sales=activity.filter(a=>a.type==='out'), byCategory={}, bySupplier={}; products.forEach(p=>{const key=p.category||'Uncategorized';byCategory[key]=(byCategory[key]||0)+p.stock;}); purchases.forEach(a=>{const key=a.ref||'Unknown supplier';bySupplier[key]=(bySupplier[key]||0)+(Number(a.qty)||0);}); return { purchases, sales, byCategory, bySupplier, low:products.filter(p=>p.stock>0&&p.stock<=p.min), out:products.filter(p=>p.stock<=0), fast:[...products].sort((a,b)=>activity.filter(x=>x.product===b.name&&x.type==='out').reduce((s,x)=>s+x.qty,0)-activity.filter(x=>x.product===a.name&&x.type==='out').reduce((s,x)=>s+x.qty,0)).slice(0,10), slow:[...products].sort((a,b)=>activity.filter(x=>x.product===a.name&&x.type==='out').length-activity.filter(x=>x.product===b.name&&x.type==='out').length).slice(0,10), dead:products.filter(p=>!activity.some(a=>a.product===p.name&&a.type==='out'))}; };
