document.querySelector('#login-form').addEventListener('submit',event=>{event.preventDefault();event.stopImmediatePropagation();const username=document.querySelector('#login-username').value.trim().toLowerCase(),password=document.querySelector('#login-password').value;if(username!=='admin'||password!=='admin123'){document.querySelector('#login-error').textContent='Use admin as username and admin123 as password.';return}currentRole='admin';sessionStorage.setItem('godown-role','admin');document.querySelector('#login-error').textContent='';document.querySelector('#login-screen').classList.add('hidden');document.querySelector('.app-shell').classList.add('ready');render()},true);
async function loadServerState(){if(!firebaseUser){stockLog('Firestore sync waiting for anonymous auth');return}try{stockLog('Starting realtime listener',sharedInventoryRef.path);onSnapshot(sharedInventoryRef,snapshot=>{if(replacingInventory){stockLog('Ignoring old snapshot during Excel replacement');return}const state=snapshot.exists()?snapshot.data():{};stockLog('Realtime snapshot received',{exists:snapshot.exists(),products:(state.products||[]).length});if(snapshot.exists()){products=state.products||[];activity=state.movements||[];priceHistory=state.priceHistory||priceHistory;suppliers=state.suppliers||suppliers;customers=state.customers||customers;localStorage.setItem('godown-products',JSON.stringify(products));localStorage.setItem('godown-activity',JSON.stringify(activity));localStorage.setItem('godown-price-history',JSON.stringify(priceHistory));localStorage.setItem('godown-suppliers',JSON.stringify(suppliers));localStorage.setItem('godown-customers',JSON.stringify(customers));}else if(products.length||activity.length||priceHistory.length||suppliers.length||customers.length){saveFirebaseState().catch(error=>console.error('[stock] initial Firestore upload failed',error))}sharedStateReady=true;if(currentRole==='admin'){document.querySelector('#login-screen').classList.add('hidden');document.querySelector('.app-shell').classList.add('ready');render()}} ,error=>console.error('[stock] realtime Firebase listener failed',error))}catch(error){console.error('[stock] Firestore listener setup failed',error)}}
async function saveFirebaseState(){if(!firebaseUser||!sharedStateReady||skipNextStateSync){stockLog('Firestore save skipped',{hasUser:Boolean(firebaseUser),ready:sharedStateReady,skipped:skipNextStateSync});if(!navigator.onLine)setSyncStatus('offline · pending');return}pendingFirebaseWrite=true;setSyncStatus('syncing...');stockLog('Saving shared inventory',{products:products.length,movements:activity.length});try{await setDoc(sharedInventoryRef,{products,movements:activity,priceHistory,suppliers,customers,updatedAt:new Date().toISOString()},{merge:true});localStorage.removeItem('godown-pending-sync');replacingInventory=false;setSyncStatus('synced');stockLog('Shared inventory saved');const latest=activity[0];const activityKey=latest?`${latest.createdAt||latest.time}|${latest.type}|${latest.product||''}|${latest.items?.length||''}`:'';if(activityKey&&activityKey!==lastSavedActivityKey){lastSavedActivityKey=activityKey;const label=latest.type==='out'?'Sale saved':latest.type==='in'?'Stock in saved':latest.type==='edit'?'Product changes saved':latest.type==='delete'?'Product deleted':'Changes saved';showToast(`${label} · Shared inventory saved`,'success')}}catch(error){localStorage.setItem('godown-pending-sync','pending');setSyncStatus('retry pending');console.error('[stock] Firestore save failed',error);showToast('Could not save to shared inventory. It will retry when connected.','error');throw error}finally{pendingFirebaseWrite=false}}
