document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-product]'),remove=e.target.closest('[data-delete-product]');if(edit&&currentRole==='admin'){const p=products.find(item=>item.id===Number(edit.dataset.editProduct));if(p)openProductModal(p)}if(remove&&currentRole==='admin'){const p=products.find(item=>item.id===Number(remove.dataset.deleteProduct));if(p){pendingDeleteId=p.id;$('#delete-product-description').textContent=`${p.name} · ${p.category||'Uncategorized'} · ${p.variant} currently has ${p.stock} pieces.`;$('#delete-modal').classList.remove('hidden')}}});
document.querySelector('#product-form').addEventListener('submit',e=>{if(!editingProductId)return;e.preventDefault();e.stopImmediatePropagation();const p=products.find(item=>item.id===editingProductId);if(p){const before=`${p.name} · ${p.category||'Uncategorized'} · ${p.code} · ${p.variant} · ${p.stock} pcs`;p.name=$('#new-name').value.trim();p.category=$('#new-category').value.trim();p.code=$('#new-code').value.trim()||p.code;p.variant=$('#new-variant').value.trim();p.stock=Math.max(0,Number($('#new-stock').value));p.price=Number($('#new-price').value) || 0;p.min=Math.max(0,Number($('#new-min').value));const after=`${p.name} · ${p.category} · ${p.code} · ${p.variant} · ${p.stock} pcs`;activity.unshift({type:'edit',product:p.name,variant:p.variant,before,after,time:'Just now'});save();editingProductId=null;$('#product-modal').classList.add('hidden');render()}},true);
$('#close-delete-modal').onclick=()=>$('#delete-modal').classList.add('hidden');$('#confirm-delete').onclick=()=>{if(pendingDeleteId!==null){const removed=products.find(item=>item.id===pendingDeleteId);products=products.filter(item=>item.id!==pendingDeleteId);activity.unshift({type:'delete',product:removed.name,variant:removed.variant,qty:removed.stock,ref:`Deleted by ${currentRole==='admin'?'Owner':'Entry Staff'}`,time:'Just now'});pendingDeleteId=null;save();$('#delete-modal').classList.add('hidden');render()}};
const totalStock = () => products.reduce((sum,p)=>sum+p.stock,0);
const lowStock = () => products.filter(p=>p.stock<=p.min);
const formatTime = value => value === 'Just now' ? 'Just now' : new Date(value).toLocaleString('en-IN',{dateStyle:'medium',timeStyle:'short'});
const money = value => `₹${Number(value||0).toLocaleString('en-IN')}`;
function notifyTelegram(text){if(!firebaseUser)return;const endpoint=location.hostname==='localhost'||location.hostname==='127.0.0.1'?'/api/telegram/notify':'/.netlify/functions/telegram-notify';fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({text})}).then(response=>{if(!response.ok)throw new Error(`Telegram endpoint returned ${response.status}`);stockLog('Telegram notification sent')}).catch(error=>console.warn('[stock] Telegram notification unavailable.',error));}
function productTelegramText(action,product,extra=''){return `Godown Stock Log\nAction: ${action}\nProduct: ${product.name}\nCategory: ${product.category||'Uncategorized'}\nSKU: ${product.code||'-'}\nSize / Variant: ${product.variant||'-'}\nPrice: ${money(product.price)}/pc\nStock: ${product.stock} pcs${extra?`\n${extra}`:''}\nDate: ${new Date().toLocaleString('en-IN')}\nBy: ${currentRole==='admin'?'Owner':'Entry Staff'}`;}
let lastTelegramActivityKey = '';
function notifyLatestActivity(){const item=activity[0];if(!item)return;const key=`${item.createdAt||item.time}|${item.type}|${item.product}|${item.variant}|${item.qty||''}|${item.items?.length||''}`;if(key===lastTelegramActivityKey)return;lastTelegramActivityKey=key;if(item.items?.length){const isSale=item.type==='out',action=isSale?'SALE / STOCK DISPATCHED':'STOCK RECEIVED / PURCHASE',lines=item.items.map((line,index)=>{const before=Number(line.beforeStock)||0,quantity=Number(line.qty)||0,remaining=Number(line.afterStock)||0;return `${index+1}. ${line.name} ${line.variant||''}\n\nSKU: ${line.code||'-'}\nSize: ${line.variant||'-'}\n\nBefore Stock: ${before} pcs\n${isSale?'Dispatched':'Received'}: ${quantity} pcs\nRemaining: ${remaining} pcs\n\nRate: ${money(line.rate)}/pc\nAmount: ${money(line.amount)}`}).join('\n\n━━━━━━━━━━━━━━\n\n'),totalAmount=item.items.reduce((sum,line)=>sum+(Number(line.amount)||0),0),totalBefore=item.items.reduce((sum,line)=>sum+(Number(line.beforeStock)||0),0),totalRemaining=item.items.reduce((sum,line)=>sum+(Number(line.afterStock)||0),0);notifyTelegram(`🏭 GODOWN ${action}\n\n📅 Date: ${new Date(item.createdAt||Date.now()).toLocaleString('en-IN')}\n👤 ${isSale?'Customer':'Supplier'}: ${item.party||'-'}\n📄 Reference: ${item.reference||'-'}\n👨‍💼 By: ${currentRole==='admin'?'Owner':'Entry Staff'}\n\n━━━━━━━━━━━━━━\n\n${lines}\n\n━━━━━━━━━━━━━━\n\n📊 TOTAL\n\nTotal Items: ${item.items.length}\nTotal Quantity: ${item.qty} pcs\nTOTAL: ${money(totalAmount)}\n\n📦 Total Before Stock: ${totalBefore} pcs\n${isSale?'📤 Total Dispatched':'📥 Total Received'}: ${item.qty} pcs\n📥 Total Remaining: ${totalRemaining} pcs\n\n━━━━━━━━━━━━━━\n✅ STOCK UPDATED`);return}const product=products.find(p=>p.name===item.product&&p.variant===item.variant)||{name:item.product,category:item.category,code:item.code,variant:item.variant,price:item.price,stock:item.afterStock??item.qty??0};notifyTelegram(productTelegramText(item.type==='in'?'Stock received':item.type==='out'?'Sale / stock dispatched':item.type==='edit'?'Product edited':'Product deleted',product,`Quantity: ${item.qty||'-'} pcs\nReference: ${item.ref||item.after||'-'}`));}
function exportReport(){const rows=[['Product','Category','SKU','Size / Variant','Price per piece','Stock','Low-stock alert'],...products.map(p=>[p.name,p.category||'Uncategorized',p.code||'',p.variant||'',p.price||0,p.stock,p.min])];activity.forEach(a=>rows.push(['LOG',a.type,a.product,a.variant,a.price||0,a.qty||'',a.ref||'']));const csv=rows.map(row=>row.map(value=>`"${String(value??'').replace(/"/g,'""')}"`).join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`godown-stock-report-${new Date().toISOString().slice(0,10)}.csv`;link.click();URL.revokeObjectURL(url);}
function save(){activity.forEach(item=>{if(!item.createdAt)item.createdAt=new Date().toISOString()});localStorage.setItem('godown-products',JSON.stringify(products));localStorage.setItem('godown-suppliers',JSON.stringify(suppliers));localStorage.setItem('godown-customers',JSON.stringify(customers));if(!navigator.onLine)localStorage.setItem('godown-pending-sync','pending');notifyLatestActivity();if(firebaseUser&&!skipNextStateSync)saveFirebaseState().catch(error=>console.warn('Firestore save unavailable; local copy retained.',error));skipNextStateSync=false;}
function productRows(list=products){return list.map(p=>{const priceText = Number(p.price) ? ` · ₹${Number(p.price).toLocaleString('en-IN')}/pc` : '',category=(p.category||p.name||'').trim(),code=String(p.code||'').trim(),sizeMatches=String(p.variant||'').match(/\d+(?:\.\d+)?\s*(?:mm|cm|in|\")/ig)||[],shortVariant=sizeMatches.at(-1)||'',sku=/\d+(?:\.\d+)?\s*(?:mm|cm|in|\")/i.test(code)?code:[code,shortVariant].filter(Boolean).join(' '),label=sku?`${category} - ${sku}`:category; return `<tr><td class="product-cell"><span class="product-sku-line">${label}</span>${priceText?`<small>${priceText}</small>`:''}</td><td class="stock-number ${p.stock<=p.min?'stock-low':'stock-ok'}">${p.stock.toLocaleString()} pcs</td><td>${p.min} pcs</td><td><span class="pill ${p.stock<=p.min?'out':'in'}">${p.stock<=p.min?'Low stock':'In stock'}</span>${currentRole==='admin'?` <span class="row-actions"><button class="row-action delete" data-delete-product="${p.id}">Delete</button></span>`:''}</td></tr>`;}).join('') || '<tr><td colspan="4" class="empty">No matching products found</td></tr>';
}
function activityRows(list=activity.slice(0,5)){return list.map(a=>{const labels={in:['Stock received','↓',''],out:['Stock dispatched','↑','out'],edit:['Product edited','✎',''],delete:['Product deleted','×','out']},label=labels[a.type]||labels.edit,groupedDetail=a.items?.length?`<br><span class="audit-change"><b>${a.type==='in'?'Department / Supplier':'Customer'}:</b> ${a.party||'-'}<br><b>Reference:</b> ${a.reference||'-'}<br>${a.items.map(item=>`${item.name} · SKU ${item.code||'-'} · ${item.qty} pcs × ${money(item.rate)}/pc`).join('<br>')}<br><b>Total:</b> ${money(a.items.reduce((sum,item)=>sum+item.amount,0))}</span>`:'',movementDetail=(a.type==='in'||a.type==='out')&&a.beforeStock!==undefined?`<br><span class="audit-change"><b>Party / Reference:</b> ${a.ref||'-'}<br><b>Price:</b> ${money(a.price)}/pc<br><b>Before:</b> ${a.beforeStock} pcs<br><b>${a.type==='in'?'Added':'Dispatched'}:</b> ${a.stockChange||a.qty} pcs<br><b>After:</b> ${a.afterStock} pcs</span>`:'',editDetail=a.type==='edit'?`<br><span class="audit-change"><b>Before:</b> ${a.before}<br><b>After:</b> ${a.after}</span>`:'';return `<div class="activity-item"><div class="activity-icon ${label[2]}">${label[1]}</div><div><b>${label[0]}${a.qty?` · ${a.qty} pcs`:''}</b><p><strong class="activity-sku">${a.items?.length?`${a.items.length} SKU(s)`:`SKU: ${a.code||'-'}`}</strong><br>${a.product} · ${a.variant||''}${groupedDetail||movementDetail||editDetail||(!movementDetail&&!editDetail&&a.ref?`<br>${a.ref}`:'')}</p></div><time>${formatTime(a.createdAt||a.time)}</time></div>`}).join('') || '<div class="empty">No activity yet</div>';}
const originalActivityRows=activityRows;
activityRows=function(list=activity.slice(0,5)){const enhanced=list.map(item=>item.items?.length?({...item,items:item.items.map((line,index)=>({...line,name:`${line.name}<br><b>Before:</b> ${line.beforeStock??'-'} pcs · <b>${item.type==='in'?'Added':'Dispatched'}:</b> ${line.qty??0} pcs · <b>After:</b> ${line.afterStock??'-'} pcs${index===0&&item.discountPercent?`<br><b>Subtotal:</b> ${money(item.subtotal)} · <b>Discount:</b> ${item.discountPercent}% (-${money(item.discountAmount)}) · <b>After discount:</b> ${money(item.afterDiscount)} · <b>GST:</b> ${money(item.gstAmount)} · <b>Final total:</b> ${money(item.finalTotal)}`:''}`}))}):item);return originalActivityRows(enhanced)};
function emptyInventory(){return `<div class="empty">No products added yet. Start by entering your actual catalogue items and opening piece count.</div>`}
function movementActions(){return `<div><button class="primary-button" id="add-product">+ Add product</button> <button class="primary-button" id="add-purchase">Stock ↓</button> <button class="primary-button" id="add-sale" style="background:var(--orange)">Sale ↑</button></div>`}
const stockHealthSummary=()=>{const low=lowStock().filter(product=>product.stock>0),out=products.filter(product=>product.stock<=0);return `<div class="stock-health-grid"><button class="stock-health-card low" type="button" data-stock-summary="low"><span><b>LOW STOCK</b><small>Below alert threshold</small></span><strong>${low.length}</strong><em>View summary →</em></button><button class="stock-health-card out" type="button" data-stock-summary="out"><span><b>OUT OF STOCK</b><small>No pieces available</small></span><strong>${out.length}</strong><em>View summary →</em></button></div>`};
function overview(){const today=new Date().toDateString();return `<section class="main-view"><div class="view-head"><div><div class="eyebrow">LIVE SNAPSHOT · SINGLE GODOWN</div><h2>Stock at a glance</h2></div>${movementActions()}</div><div class="metric-grid"><div class="metric-card"><p>TOTAL PIECES</p><strong>${totalStock().toLocaleString()}</strong><small>↑ Live count</small></div><div class="metric-card"><p>PRODUCT VARIANTS</p><strong>${products.length}</strong><small>Added by you</small></div><div class="metric-card"><p>STOCK IN · TODAY</p><strong>${activity.filter(a=>a.type==='in'&&new Date(a.createdAt||a.time).toDateString()===today).reduce((s,a)=>s+a.qty,0).toLocaleString()}</strong><small>↑ Received</small></div><div class="metric-card"><p>LOW STOCK ITEMS</p><strong>${lowStock().length}</strong><small class="trend-down">Needs attention</small></div></div><div class="metric-grid monthly-metric-grid"><div class="metric-card"><p>MONTH SALE</p><strong>${money(monthValue('out'))}</strong><small>1st to month end</small></div><div class="metric-card"><p>MONTH STOCK IN</p><strong>${money(monthValue('in'))}</strong><small>1st to month end</small></div><div class="metric-card"><p>NET CHANGE · THIS MONTH</p><strong>${signedMoney(monthNetStockValue())}</strong><small>Stock-in value minus sales</small></div></div>${stockHealthSummary()}<div class="content-grid"><div class="panel"><div class="panel-head"><h3>Current inventory</h3><a data-go="inventory">View all →</a></div><div class="table-wrap">${products.length?`<table class="data-table"><thead><tr><th>Product / variant</th><th>Available</th><th>Alert at</th><th>Status</th></tr></thead><tbody>${productRows(products.slice(0,5))}</tbody></table>`:emptyInventory()}</div></div><div class="panel"><div class="panel-head"><h3>Recent activity</h3><a data-go="activity">View log →</a></div><div class="activity-list">${activityRows()}</div></div></div></section>`}
const isExcelImport=item=>String(item.ref||'').toLowerCase().includes('excel import');
const activityValue=item=>item.items?.length?Number(item.finalTotal??item.totalAmount??item.items.reduce((sum,line)=>sum+(Number(line.amount)||((Number(line.qty)||0)*(Number(line.rate)||0))),0)):(Number(item.qty)||0)*(Number(item.transactionPrice??item.price)||0);
const localDateKey=(date=new Date())=>{const year=date.getFullYear(),month=String(date.getMonth()+1).padStart(2,'0'),day=String(date.getDate()).padStart(2,'0');return `${year}-${month}-${day}`};
const isOnLocalDate=(item,dateKey=localDateKey())=>{const date=new Date(item.createdAt||item.time);return !Number.isNaN(date.getTime())&&localDateKey(date)===dateKey};
const todayValue=(type,predicate=()=>true)=>activity.filter(item=>item.type===type&&!isExcelImport(item)&&predicate(item)&&isOnLocalDate(item)).reduce((sum,item)=>sum+activityValue(item),0);
const isInCurrentMonth=item=>{const date=new Date(item.createdAt||item.time),now=new Date();return !Number.isNaN(date.getTime())&&!isExcelImport(item)&&date.getFullYear()===now.getFullYear()&&date.getMonth()===now.getMonth()};
const monthValue=type=>activity.filter(item=>item.type===type&&isInCurrentMonth(item)).reduce((sum,item)=>sum+activityValue(item),0);
const monthNetStockValue=()=>monthValue('in')-monthValue('out');
const monthActivity=()=>activity.filter(isInCurrentMonth);
const monthPieces=type=>monthActivity().filter(item=>item.type===type).reduce((sum,item)=>sum+(Number(item.qty)||0),0);
const stockMovementValue=item=>{const lineValue=item.items?.length?item.items.reduce((sum,line)=>sum+(Number(line.amount)||((Number(line.qty)||0)*(Number(line.rate)||0))),0):(Number(item.qty)||0)*(Number(item.transactionPrice??item.price)||0);return lineValue||Number(item.subtotal??item.finalTotal??activityValue(item))||0};
const monthlyDayRows=()=>{const days={};monthActivity().forEach(item=>{const date=new Date(item.createdAt||item.time),key=localDateKey(date);days[key]??={inValue:0,outValue:0,inStockValue:0,outStockValue:0,inPieces:0,outPieces:0};const value=activityValue(item),stockValue=stockMovementValue(item);if(item.type==='in'){days[key].inValue+=value;days[key].inStockValue+=stockValue;days[key].inPieces+=Number(item.qty)||0}else if(item.type==='out'){days[key].outValue+=value;days[key].outStockValue+=stockValue;days[key].outPieces+=Number(item.qty)||0}});const orderedDays=Object.entries(days).sort(([a],[b])=>a.localeCompare(b)),endingValueFor=dateKey=>totalStockValue()-orderedDays.filter(([key])=>key>dateKey).reduce((sum,[,day])=>sum+day.inStockValue-day.outStockValue,0);let running=0;return orderedDays.map(([date,day])=>{const net=day.inValue-day.outValue;running+=net;const display=new Date(`${date}T00:00:00`).toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'});return `<div class="monthly-day-row"><div><b>${display}</b><small>${day.inPieces.toLocaleString()} pcs in · ${day.outPieces.toLocaleString()} pcs sold</small></div><span class="monthly-day-value in">+${money(day.inValue)}</span><span class="monthly-day-value out">-${money(day.outValue)}</span><strong class="${net>=0?'positive':'negative'}">${signedMoney(net)}</strong><strong class="monthly-ending-stock">${money(endingValueFor(date))}</strong><small class="monthly-running">Running: ${signedMoney(running)}</small></div>`}).join('')||'<div class="empty">No movements recorded this month.</div>'};
function monthlySummaryView(kind){const items=monthActivity().filter(item=>kind==='sale'?item.type==='out':kind==='stock'?item.type==='in':item.type==='in'||item.type==='out'),allMonthItems=monthActivity(),sales=monthValue('out'),stockIn=monthValue('in'),net=stockIn-sales,title=kind==='sale'?'Month sales summary':kind==='stock'?'Month stock-in summary':'This month net change';return `<section class="main-view"><div class="view-head"><div><div class="eyebrow">AUDIT PROOF · CURRENT MONTH</div><h2>${title}</h2></div><button class="filter-select" id="monthly-summary-back" type="button">← Back to Home</button></div><div class="metric-grid monthly-summary-metrics"><div class="metric-card"><p>MONTH SALE</p><strong>${money(sales)}</strong><small>${monthPieces('out').toLocaleString()} pcs</small></div><div class="metric-card"><p>MONTH STOCK IN</p><strong>${money(stockIn)}</strong><small>${monthPieces('in').toLocaleString()} pcs</small></div><div class="metric-card"><p>NET CHANGE</p><strong>${signedMoney(net)}</strong><small>Stock-in minus sales</small></div></div><div class="panel monthly-day-panel"><div class="panel-head"><h3>Day-wise value proof</h3><span class="eyebrow" style="margin:0">${allMonthItems.length} movements</span></div><div class="monthly-day-head"><span>Date</span><span>Stock in</span><span>Sale</span><span>Net</span><span>Stock value at day end</span><span>Running</span></div><div class="monthly-day-list">${monthlyDayRows()}</div></div><div class="panel"><div class="panel-head"><h3>${kind==='net'?'All movements this month':kind==='sale'?'Sales this month':'Stock received this month'}</h3><span class="eyebrow" style="margin:0">${items.length} entries</span></div><div class="activity-list">${activityRows(items)}</div></div><div class="panel monthly-proof-panel"><div class="panel-head"><h3>Month value proof</h3></div><div class="net-change-total"><span>${money(stockIn)} stock in − ${money(sales)} sales</span><strong>${signedMoney(net)}</strong></div></div></section>`}
const todayNetStockValue=()=>{const today=new Date().toDateString();return activity.filter(item=>{const date=new Date(item.createdAt||item.time);return !isExcelImport(item)&&!Number.isNaN(date.getTime())&&date.toDateString()===today}).reduce((sum,item)=>{const value=activityValue(item);return sum+(item.type==='in'?value:item.type==='out'?-value:0)},0)};
const signedMoney=value=>value>=0?`+${money(value)}`:`-${money(Math.abs(value))}`;
const totalStockValue=()=>products.reduce((sum,product)=>sum+(Number(product.stock)||0)*(Number(product.price)||0),0);
const originalOverview=overview;
overview=()=>originalOverview().replace(/<p>TOTAL PIECES<\/p><strong>[^<]*<\/strong><small>[^<]*<\/small>/,`<p>TODAY'S SALE</p><strong>${money(todayValue('out'))}</strong><small>Amount sold</small>`).replace(/<p>PRODUCT VARIANTS<\/p><strong>[^<]*<\/strong><small>[^<]*<\/small>/,`<p>CURRENT STOCK VALUE</p><strong>${money(totalStockValue())}</strong><small>Current stock value</small>`).replace(/<p>STOCK IN · TODAY<\/p><strong>[^<]*<\/strong><small>[^<]*<\/small>/,`<p>NET CHANGE · TODAY</p><strong>${signedMoney(todayNetStockValue())}</strong><small>Stock-in value minus sales</small>`).replace(/<p>LOW STOCK ITEMS<\/p><strong>[^<]*<\/strong><small[^>]*>[^<]*<\/small>/,`<p>TODAY'S STOCK IN</p><strong>${money(todayValue('in'))}</strong><small>Value received</small>`);
const overviewWithArrows=overview;overview=()=>overviewWithArrows().replace(`<p>TODAY'S SALE</p>`,`<p class="metric-sale">TODAY'S SALE <span>↑</span></p>`).replace(`<p>TODAY'S STOCK IN</p>`,`<p class="metric-stock-in">TODAY'S STOCK IN <span>↓</span></p>`);
function inventory(){return `<section class="main-view"><div class="view-head"><div><div class="eyebrow">PRODUCT MASTER · PIECES ONLY</div><h2>Inventory</h2></div>${movementActions()}</div><div class="search-bar"><span>⌕</span><input id="inventory-search" placeholder="Search product, category, code or finish..."/><select class="filter-select" id="stock-filter"><option value="all">All stock</option><option value="low">Low stock</option><option value="ok">In stock</option></select></div><div class="panel"><div class="table-wrap"><table class="data-table"><thead><tr><th>Product / category / variant</th><th>Available pieces</th><th>Alert threshold</th><th>Status</th></tr></thead><tbody id="inventory-body">${products.length?productRows():`<tr><td colspan="4">${emptyInventory()}</td></tr>`}</tbody></table></div></div></section>`}
function activityView(){const today=new Date().toDateString(),list=currentActivityFilter==='today-in'?activity.filter(item=>item.type==='in'&&new Date(item.createdAt||item.time).toDateString()===today):currentActivityFilter==='today-out'?activity.filter(item=>item.type==='out'&&new Date(item.createdAt||item.time).toDateString()===today):activity,isTodayIn=currentActivityFilter==='today-in',isTodayOut=currentActivityFilter==='today-out';return `<section class="main-view"><div class="view-head"><div><div class="eyebrow">AUDIT TRAIL · EVERY MOVEMENT</div><h2>${isTodayIn?'Stock received today':isTodayOut?'Sales today':'Activity log'}</h2></div><button class="primary-button" id="add-movement">+ Add movement</button></div><div class="panel"><div class="panel-head"><h3>${isTodayIn?"Today's stock received":isTodayOut?"Today's sales":'All stock movements'}</h3><span class="eyebrow" style="margin:0">${list.length} entries</span></div><div class="activity-list">${activityRows(list)}</div></div></section>`}
function reports(){const ins=activity.filter(a=>a.type==='in').reduce((s,a)=>s+a.qty,0), outs=activity.filter(a=>a.type==='out').reduce((s,a)=>s+a.qty,0);return `<section class="main-view"><div class="view-head"><div><div class="eyebrow">INSIGHTS · MOVEMENT SUMMARY</div><h2>Reports</h2></div><button class="primary-button" id="export-report">Export report <span>↓</span></button></div><div class="report-grid"><div class="report-card"><h3>Movement summary</h3><div class="bar-row"><div class="bar-label"><span>Stock received</span><b>${ins.toLocaleString()} pcs</b></div><div class="bar"><i style="width:${Math.min(100,ins/(ins+outs||1)*100)}%"></i></div></div><div class="bar-row"><div class="bar-label"><span>Stock dispatched</span><b>${outs.toLocaleString()} pcs</b></div><div class="bar"><i class="orange" style="width:${Math.min(100,outs/(ins+outs||1)*100)}%"></i></div></div></div><div class="report-card"><h3>Stock health</h3><div class="bar-row"><div class="bar-label"><span>Healthy variants</span><b>${products.length-lowStock().length} / ${products.length}</b></div><div class="bar"><i style="width:${(products.length-lowStock().length)/(products.length||1)*100}%"></i></div></div><div class="bar-row"><div class="bar-label"><span>Needs attention</span><b>${lowStock().length} variants</b></div><div class="bar"><i class="orange" style="width:${lowStock().length/(products.length||1)*100}%"></i></div></div></div><div class="report-card"><h3>Quick actions</h3><button class="primary-button" style="width:100%;margin-bottom:10px" id="report-movement">Record movement →</button><button class="filter-select" style="width:100%;cursor:pointer" id="whatsapp-report">Share summary on WhatsApp ↗</button></div></div></section>`}
function render(){const views={overview,inventory,activity:activityView,reports},requestedView=currentView,viewRenderer=views[requestedView]||views.overview;if(!views[requestedView])currentView='overview';$('#view-container').innerHTML=viewRenderer();$('#crumb-view').textContent=currentView.toUpperCase();$('#page-title').innerHTML=currentView==='overview'?'Good morning <span>✦</span>':currentView[0].toUpperCase()+currentView.slice(1);const roleName=currentRole==='admin'?'Owner':'Entry Staff',avatar=currentRole==='admin'?'OW':'ES';$('#user-name').textContent=roleName;$('#user-avatar').textContent=avatar;$('#sidebar-role').textContent=roleName;$('#sidebar-avatar').textContent=avatar;document.querySelectorAll('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.view===currentView));document.querySelectorAll('[data-admin-only]').forEach(x=>x.classList.toggle('hidden',currentRole!=='admin'));bindView();}
