const partyMasterView=type=>{const isCustomer=type==='customers',list=isCustomer?customers:suppliers,title=isCustomer?'Customers':'Suppliers',description=isCustomer?'Add individual parties who buy stock.':'Add manufacturing departments and map each department to its product category and supervisor.';return `<section class="main-view"><div class="view-head"><div><div class="eyebrow">PARTY MASTER · ${title.toUpperCase()}</div><h2>${title}</h2></div></div><div class="party-master-panel panel"><p class="party-master-help">${description}</p><form id="party-master-form" class="party-master-form"><input id="party-name" required maxlength="80" placeholder="Enter ${isCustomer?'customer':'department'} name">${isCustomer?'':`<select id="party-category" required><option value="">Select category</option>${categoryOptions().map(category=>`<option value="${category}">${category}</option>`).join('')}</select><input id="party-supervisor" required maxlength="80" placeholder="Supervisor name">`}<button class="primary-button" type="submit">Add ${isCustomer?'customer':'department'} <span>+</span></button></form><div class="party-list">${list.map((party,index)=>{const name=partyName(party);return `<div class="party-row"><span><b>${name}</b>${!isCustomer&&partyCategory(party)?`<small>${partyCategory(party)} · Supervisor: ${partySupervisor(party)}</small>`:''}</span><button type="button" class="row-action delete" data-delete-party="${type}:${index}">Delete</button></div>`}).join('')||'<div class="empty">No names added yet.</div>'}</div></div></section>`};
