const refreshVoucherSearchFilters=()=>document.querySelectorAll('.voucher-line:not(.voucher-line-head)').forEach(line=>{const search=line.querySelector('[data-voucher-search]'),select=line.querySelector('[data-voucher-product]'),suggestions=line.querySelector('.voucher-suggestions');if(!search||!select||!suggestions)return;search.oninput=()=>{const term=search.value.trim().toLowerCase(),allowed=new Set([...select.options].map(option=>option.value));suggestions.replaceChildren();if(term.length<2){suggestions.classList.add('hidden');return}products.filter(product=>allowed.has(String(product.id))&&`${product.code||''} ${product.name||''} ${product.variant||''}`.toLowerCase().includes(term)).slice(0,8).forEach(product=>{const option=document.createElement('button');option.type='button';option.className='voucher-suggestion';option.textContent=`${product.code||'NO-SKU'} · ${product.name} · ${product.variant}`;option.onclick=()=>{select.value=String(product.id);select.dispatchEvent(new Event('change'));};suggestions.append(option)});suggestions.classList.toggle('hidden',!suggestions.childElementCount)}});
