const addVoucherSearchFields=()=>{document.querySelectorAll('.voucher-line:not(.voucher-line-head)').forEach((line,index)=>{if(line.querySelector('[data-voucher-search]'))return;const select=line.querySelector('[data-voucher-product]');if(!select)return;const search=document.createElement('input'),suggestions=document.createElement('div');search.type='search';search.placeholder='Search SKU, product or variant';search.setAttribute('data-voucher-search','');suggestions.className='voucher-suggestions hidden';search.oninput=()=>{const term=search.value.trim().toLowerCase();suggestions.replaceChildren();if(term.length<2){suggestions.classList.add('hidden');return}products.filter(product=>`${product.code||''} ${product.name||''} ${product.variant||''}`.toLowerCase().includes(term)).slice(0,8).forEach(product=>{const option=document.createElement('button');option.type='button';option.className='voucher-suggestion';option.textContent=`${product.code||'NO-SKU'} · ${product.name} · ${product.variant}`;option.onclick=()=>{select.value=String(product.id);select.dispatchEvent(new Event('change'));};suggestions.append(option)});suggestions.classList.toggle('hidden',!suggestions.childElementCount)};const picker=document.createElement('div');picker.className='voucher-picker';picker.append(search,suggestions);select.before(picker)})};
