const openVoucherPicker=(search,select)=>{const modal=document.createElement('div');modal.id='voucher-picker-modal';modal.className='voucher-picker-modal';modal.innerHTML='<div class="voucher-picker-dialog" role="dialog" aria-modal="true"><div class="voucher-picker-title"><h3>Select stock item</h3><button type="button" id="close-voucher-picker">×</button></div><input id="voucher-picker-query" type="search" placeholder="Type SKU, product or variant" autocomplete="off"><div id="voucher-picker-results" role="listbox"></div></div>';document.body.append(modal);const query=modal.querySelector('#voucher-picker-query'),results=modal.querySelector('#voucher-picker-results');voucherPickerState={search,select,items:[],active:0};const renderResults=()=>{const term=query.value.trim().toLowerCase();voucherPickerState.items=products.filter(product=>`${product.code||''} ${product.name||''} ${product.variant||''}`.toLowerCase().includes(term));voucherPickerState.active=Math.min(voucherPickerState.active,Math.max(0,voucherPickerState.items.length-1));results.replaceChildren();if(!voucherPickerState.items.length){results.textContent='No matching stock item';return}voucherPickerState.items.forEach((product,index)=>{const option=document.createElement('button');option.type='button';option.className=`voucher-picker-option ${index===voucherPickerState.active?'active':''}`;option.innerHTML=`<b>${product.code||'NO-SKU'}</b><span>${product.name} · ${product.variant}</span><small>${product.stock} pcs · ${money(product.price)}/pc</small>`;option.onclick=()=>selectProduct(index);results.append(option)})};const selectProduct=index=>{const product=voucherPickerState.items[index];if(!product)return;select.value=String(product.id);search.value=`${product.code||'NO-SKU'} · ${product.name} · ${product.variant}`;select.dispatchEvent(new Event('change'));closeVoucherPicker()};query.oninput=()=>{voucherPickerState.active=0;renderResults()};query.onkeydown=event=>{if(event.key==='ArrowDown'){event.preventDefault();voucherPickerState.active=Math.min(voucherPickerState.active+1,voucherPickerState.items.length-1);renderResults()}else if(event.key==='ArrowUp'){event.preventDefault();voucherPickerState.active=Math.max(voucherPickerState.active-1,0);renderResults()}else if(event.key==='Enter'){event.preventDefault();selectProduct(voucherPickerState.active)}else if(event.key==='Escape')closeVoucherPicker()};modal.querySelector('#close-voucher-picker').onclick=closeVoucherPicker;modal.onclick=event=>{if(event.target===modal)closeVoucherPicker()};renderResults();query.focus()};
