function replacePurchaseLabels(root=document.querySelector('#view-container')){if(!root)return;const replace=value=>value.replace(/Purchases/g,'Stock').replace(/Purchase/g,'Stock').replace(/purchases/g,'stock').replace(/purchase/g,'stock');const walker=document.createTreeWalker(root,NodeFilter.SHOW_TEXT);const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);nodes.forEach(node=>{node.nodeValue=replace(node.nodeValue)});root.querySelectorAll('input,textarea').forEach(input=>{input.value=replace(input.value);if(input.placeholder)input.placeholder=replace(input.placeholder)})}
const renderWithStockLabels=render;render=()=>{renderWithStockLabels();replacePurchaseLabels();ensureSalesDownloadButton()};
const renderVoucherWithStockLabels=type=>{renderVoucher(type);replacePurchaseLabels()};
document.addEventListener('click',event=>{if(event.target.closest('#add-purchase'))requestAnimationFrame(()=>replacePurchaseLabels())});
let salesChartState={range:'weekly',dimension:'sku',from:'',to:''};
const salesDate=value=>{const date=new Date(value);return Number.isNaN(date.getTime())?null:new Date(date.getFullYear(),date.getMonth(),date.getDate())};
const salesDayKey=date=>date.toISOString().slice(0,10);
function getSalesReportData(){const today=new Date(),end=new Date(today.getFullYear(),today.getMonth(),today.getDate()),start=new Date(end);if(salesChartState.range==='monthly')start.setDate(start.getDate()-29);else if(salesChartState.range==='custom'&&salesChartState.from)start.setTime(new Date(`${salesChartState.from}T00:00:00`).getTime());else start.setDate(start.getDate()-6);const finalEnd=salesChartState.range==='custom'&&salesChartState.to?new Date(`${salesChartState.to}T00:00:00`):end,sales=activity.filter(item=>item.type==='out').map(item=>({...item,date:salesDate(item.createdAt||item.time)})).filter(item=>item.date&&item.date>=start&&item.date<=finalEnd);return {start,finalEnd,sales}}
function downloadSalesChart(){const {start,finalEnd,sales}=getSalesReportData(),groupLabel=salesChartState.dimension==='category'?'Category':'SKU / Code',rows=[['SALES REPORT'],['Range',salesChartState.range==='weekly'?'Weekly':salesChartState.range==='monthly'?'Monthly':'Custom'],['From',start.toISOString().slice(0,10)],['To',finalEnd.toISOString().slice(0,10)],['Grouping',groupLabel],[],['Date','Product','Category','SKU / Code','Variant','Quantity','Rate','Amount','Reference']];sales.sort((a,b)=>a.date-b.date).forEach(item=>rows.push([salesDayKey(item.date),item.product||'',item.category||'',item.code||'',item.variant||'',Number(item.qty)||0,Number(item.transactionPrice??item.price)||0,(Number(item.qty)||0)*(Number(item.transactionPrice??item.price)||0),item.ref||'']));const totals={};sales.forEach(item=>{const key=salesChartState.dimension==='category'?(item.category||'Uncategorized'):(item.code||item.product||'Unknown SKU');totals[key]=(totals[key]||0)+(Number(item.qty)||0)});rows.push([],['SUMMARY',groupLabel,'Pieces sold']);Object.entries(totals).sort((a,b)=>b[1]-a[1]).forEach(([key,qty])=>rows.push(['',key,qty]));const csv=rows.map(row=>row.map(value=>`"${String(value??'').replace(/"/g,'""')}"`).join(',')).join('\r\n'),url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),link=document.createElement('a');link.href=url;link.download=`sales-${salesChartState.range}-${start.toISOString().slice(0,10)}-to-${finalEnd.toISOString().slice(0,10)}.csv`;link.click();URL.revokeObjectURL(url)}
function salesAnalyticsMarkup(){const today=new Date(),end=new Date(today.getFullYear(),today.getMonth(),today.getDate()),start=new Date(end);if(salesChartState.range==='monthly')start.setDate(start.getDate()-29);else if(salesChartState.range==='custom'&&salesChartState.from)start.setTime(new Date(`${salesChartState.from}T00:00:00`).getTime());else start.setDate(start.getDate()-6);const finalEnd=salesChartState.range==='custom'&&salesChartState.to?new Date(`${salesChartState.to}T00:00:00`):end;const sales=activity.filter(item=>item.type==='out').map(item=>({...item,date:salesDate(item.createdAt||item.time)})).filter(item=>item.date&&item.date>=start&&item.date<=finalEnd);const totals={};sales.forEach(item=>{const key=salesChartState.dimension==='category'?(item.category||'Uncategorized'):(item.code||item.product||'Unknown SKU');totals[key]=(totals[key]||0)+(Number(item.qty)||0)});const dates=[];for(const date=new Date(start);date<=finalEnd;date.setDate(date.getDate()+1))dates.push(new Date(date));const max=Math.max(1,...dates.map(date=>sales.filter(item=>salesDayKey(item.date)===salesDayKey(date)).reduce((sum,item)=>sum+(Number(item.qty)||0),0)));const width=760,height=230,pad=34,barWidth=Math.max(5,(width-pad*2)/Math.max(1,dates.length)-5),bars=dates.map((date,index)=>{const qty=sales.filter(item=>salesDayKey(item.date)===salesDayKey(date)).reduce((sum,item)=>sum+(Number(item.qty)||0),0),barHeight=qty?Math.max(3,(height-pad*2)*qty/max):0,x=pad+index*((width-pad*2)/Math.max(1,dates.length)),y=height-pad-barHeight;return `<rect class="sales-chart-bar" x="${x.toFixed(1)}" y="${y.toFixed(1)}" width="${barWidth.toFixed(1)}" height="${barHeight.toFixed(1)}" rx="3"><title>${date.toLocaleDateString('en-IN',{day:'2-digit',month:'short'})}: ${qty} pcs</title></rect>`}).join(''),labels=dates.filter((date,index)=>dates.length<=12||index%Math.ceil(dates.length/10)===0).map(date=>{const index=dates.findIndex(item=>salesDayKey(item)===salesDayKey(date)),x=pad+index*((width-pad*2)/Math.max(1,dates.length))+barWidth/2;return `<text x="${x.toFixed(1)}" y="${height-8}" text-anchor="middle">${date.toLocaleDateString('en-IN',{day:'2-digit',month:'short'})}</text>`}).join(''),ranked=Object.entries(totals).sort((a,b)=>b[1]-a[1]).slice(0,12).map(([name,qty])=>`<div class="sales-rank-row"><span>${name}</span><b>${qty.toLocaleString()} pcs</b></div>`).join('')||'<div class="empty">No sales for this period</div>';return `<section class="sales-analytics report-card"><div class="sales-analytics-head"><div><h3>Sales chart</h3><small>${sales.length?`${sales.reduce((sum,item)=>sum+(Number(item.qty)||0),0).toLocaleString()} pieces sold`: 'No sales'} · ${start.toLocaleDateString('en-IN')} to ${finalEnd.toLocaleDateString('en-IN')}</small></div><div class="sales-chart-controls"><button type="button" data-sales-range="weekly" class="${salesChartState.range==='weekly'?'active':''}">Weekly</button><button type="button" data-sales-range="monthly" class="${salesChartState.range==='monthly'?'active':''}">Monthly</button><button type="button" data-sales-range="custom" class="${salesChartState.range==='custom'?'active':''}">Custom</button><select id="sales-chart-dimension"><option value="sku" ${salesChartState.dimension==='sku'?'selected':''}>SKU wise</option><option value="category" ${salesChartState.dimension==='category'?'selected':''}>Category wise</option></select></div></div><div class="sales-custom-dates ${salesChartState.range==='custom'?'visible':''}"><label>From <input type="date" id="sales-from" value="${salesChartState.from}"></label><label>To <input type="date" id="sales-to" value="${salesChartState.to}"></label><button type="button" class="primary-button" id="apply-sales-dates">Apply</button></div><div class="sales-chart-layout"><div class="sales-chart-wrap"><svg class="sales-chart" viewBox="0 0 ${width} ${height}" role="img" aria-label="Sales by day"><line x1="${pad}" y1="${height-pad}" x2="${width-pad}" y2="${height-pad}"/><g class="sales-chart-bars">${bars}</g><g class="sales-chart-labels">${labels}</g></svg></div><div class="sales-rank"><h4>${salesChartState.dimension==='sku'?'SKU-wise sales':'Category-wise sales'}</h4>${ranked}</div></div></section>`}
function salesDailyBreakdown(){const today=new Date(),end=new Date(today.getFullYear(),today.getMonth(),today.getDate()),start=new Date(end);if(salesChartState.range==='monthly')start.setDate(start.getDate()-29);else if(salesChartState.range==='custom'&&salesChartState.from)start.setTime(new Date(`${salesChartState.from}T00:00:00`).getTime());else start.setDate(start.getDate()-6);const finalEnd=salesChartState.range==='custom'&&salesChartState.to?new Date(`${salesChartState.to}T00:00:00`):end,days=[];for(const date=new Date(start);date<=finalEnd;date.setDate(date.getDate()+1)){const key=salesDayKey(date),items=activity.filter(item=>item.type==='out'&&salesDate(item.createdAt||item.time)&&salesDayKey(salesDate(item.createdAt||item.time))===key),groups={};items.forEach(item=>{const name=salesChartState.dimension==='category'?(item.category||'Uncategorized'):(item.code||item.product||'Unknown SKU');groups[name]=(groups[name]||0)+(Number(item.qty)||0)});if(items.length)days.push(`<div class="sales-day-row"><strong>${date.toLocaleDateString('en-IN',{weekday:'short',day:'2-digit',month:'short'})}</strong><span>${Object.entries(groups).map(([name,qty])=>`${name}: ${qty} pcs`).join(' · ')}</span></div>`)}return `<div class="sales-daily-breakdown"><h4>Daily sales details</h4>${days.join('')||'<div class="empty">No sales for this period</div>'}</div>`}
const reportsWithSalesAnalytics=reports;reports=()=>reportsWithSalesAnalytics().replace('<div class="report-grid">',salesAnalyticsMarkup()+salesDailyBreakdown()+'<div class="report-grid">');
function ensureSalesDownloadButton(){const controls=document.querySelector('.sales-chart-controls');if(!controls||controls.querySelector('#download-sales-chart'))return;const button=document.createElement('button');button.type='button';button.id='download-sales-chart';button.className='primary-button';button.title='Download filtered sales data';button.textContent='Download CSV ↓';button.onclick=downloadSalesChart;controls.prepend(button)}
document.addEventListener('click',event=>{const range=event.target.closest('[data-sales-range]');if(range){salesChartState.range=range.dataset.salesRange;render();return}if(event.target.closest('#apply-sales-dates')){salesChartState.range='custom';salesChartState.from=document.querySelector('#sales-from')?.value||'';salesChartState.to=document.querySelector('#sales-to')?.value||'';if(salesChartState.from&&salesChartState.to&&salesChartState.from>salesChartState.to){showToast('From date must be before To date.','error');return}render()}});
document.addEventListener('change',event=>{if(event.target.matches('#sales-chart-dimension')){salesChartState.dimension=event.target.value;render()}});
document.addEventListener('click',event=>{const dayRow=event.target.closest('.monthly-day-row');if(dayRow&&currentView.startsWith('monthly-')){const dates=[...new Set(monthActivity().map(item=>localDateKey(new Date(item.createdAt||item.time))))].sort(),date=dates[[...document.querySelectorAll('.monthly-day-row')].indexOf(dayRow)];if(date){currentView='net-change';$('#view-container').innerHTML=netChangeView(date);$('#crumb-view').textContent='DAY SUMMARY';$('#page-title').textContent='Day summary';bindNetChangeView(date)}return}const card=event.target.closest('.metric-card');if(!card||currentView!=='overview')return;openMetricDestination([...document.querySelectorAll('.metric-card')].indexOf(card))},true);
document.addEventListener('click',event=>{const summary=event.target.closest('[data-stock-summary]');if(!summary||currentView!=='overview')return;const type=summary.dataset.stockSummary,items=type==='out'?products.filter(product=>product.stock<=0):products.filter(product=>product.stock>0&&product.stock<=product.min),title=type==='out'?'Out of stock summary':'Low stock summary',description=type==='out'?'Products with zero available pieces':'Products below their alert threshold',modal=document.createElement('div');modal.className='modal';modal.innerHTML=`<div class="modal-card stock-summary-modal"><div class="modal-head"><div><div class="eyebrow">INVENTORY HEALTH · ${type.toUpperCase()}</div><h2>${title}</h2><p>${description} · ${items.length} item${items.length===1?'':'s'}</p></div><button class="icon-button" type="button" data-close-stock-summary aria-label="Close summary">×</button></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Product / SKU</th><th>Available</th><th>Alert threshold</th><th>Status</th></tr></thead><tbody>${items.length?productRows(items):'<tr><td colspan="4" class="empty">No matching items.</td></tr>'}</tbody></table></div></div>`;document.body.append(modal);modal.querySelector('[data-close-stock-summary]').onclick=()=>modal.remove();},true);
document.addEventListener('click',event=>{if(event.target.matches('.modal')&&event.target.querySelector('.stock-summary-modal'))event.target.remove()},true);
document.addEventListener('keydown',event=>{if(!['Enter',' '].includes(event.key)||!event.target.matches('.metric-card')||currentView!=='overview')return;event.preventDefault();openMetricDestination([...document.querySelectorAll('.metric-card')].indexOf(event.target))},true);
const addVoucherSkuLabels=()=>document.querySelectorAll('.voucher-line:not(.voucher-line-head)').forEach(line=>{const select=line.querySelector('[data-voucher-product]'),product=products.find(item=>String(item.id)===select?.value);let label=line.querySelector('.voucher-sku');if(!label){label=document.createElement('div');label.className='voucher-sku';line.querySelector('.voucher-picker')?.after(label)}if(product){label.innerHTML=`<b>SKU / Code: ${product.code||'NO-SKU'}</b><span>${product.name} · ${product.variant}</span>`;label.classList.remove('hidden')}else{label.textContent='Select an item to see its SKU';label.classList.remove('hidden')}});
importExcelSnapshot=async function(event){const file=event.target.files[0]||window.pendingExcelFile;event.target.value='';window.pendingExcelFile=null;if(!file)return;if(!window.XLSX){showToast('Excel reader load nahi hua. Page refresh karke dobara try karo.','error');return}try{const workbook=XLSX.read(await file.arrayBuffer(),{type:'array'});let rows=[];for(const sheetName of workbook.SheetNames){const candidate=XLSX.utils.sheet_to_json(workbook.Sheets[sheetName],{defval:''});if(candidate.some(row=>String(findColumn(row,['product','item','productname','itemname','description'])).trim())){rows=candidate;break}}if(!rows.length){showToast('Excel mein Product column ya product rows nahi mile. Template ke Product column ka use karo.','error');return}const nextProducts=[],nextActivity=[];rows.forEach((row,index)=>{const name=String(findColumn(row,['product','item','productname','itemname','description'])).trim();if(!name)return;const category=String(findColumn(row,['category','group','productcategory'])).trim()||'Uncategorized',code=String(findColumn(row,['code','sku','itemcode','productcode'])).trim()||`IMPORT-${Date.now()}-${index}`,variant=String(findColumn(row,['variant','size','finish','sizevariant','model'])).trim()||'Standard',stock=Math.max(0,Number(findColumn(row,['stock','qty','quantity','pieces','closingstock','openingstock']))||0),price=Math.max(0,Number(findColumn(row,['price','rate','unitprice','priceperpiece','mrp','cost']))||0),min=Math.max(0,Number(findColumn(row,['minimum','minstock','minimumstock','alert','alertat']))||0);nextProducts.push({id:Date.now()+index,name,category,code,variant,stock,price,min});nextActivity.push({type:'in',product:name,category,code,variant,price,transactionPrice:price,qty:stock,beforeStock:0,afterStock:stock,stockChange:stock,ref:'Excel import snapshot',time:'Just now'})});products=nextProducts;activity=nextActivity;priceHistory=[];replacingInventory=true;save();render();showToast(`${nextProducts.length} products imported successfully.`,'success')}catch(error){console.error('[stock] Excel import failed',error);showToast(`Excel import failed: ${error.message||'file format check karo.'}`,'error')}};
let restoringBrowserView=false;
const currentBrowserState=()=>({view:currentView,activityFilter:currentActivityFilter});
const syncBrowserView=()=>{const state=currentBrowserState(),last=history.state;if(!last||last.view!==state.view||last.activityFilter!==state.activityFilter){if(restoringBrowserView){history.replaceState(state,'',`#${state.view}`)}else{history.pushState(state,'',`#${state.view}`)}}};
const browserViewObserver=new MutationObserver(syncBrowserView);
browserViewObserver.observe(document.querySelector('#crumb-view'),{childList:true,characterData:true,subtree:true});
history.replaceState(currentBrowserState(),'',`#${currentView}`);
window.addEventListener('popstate',event=>{const state=event.state;if(!state?.view){history.replaceState(currentBrowserState(),'',`#${currentView}`);return}restoringBrowserView=true;currentView=state.view;currentActivityFilter=state.activityFilter||'all';if(currentView==='purchase'||currentView==='sale')renderVoucher(currentView);else render();restoringBrowserView=false});
document.addEventListener('click',event=>{const voucherButton=event.target.closest('#add-purchase,#add-sale');if(!voucherButton)return;const type=voucherButton.id==='add-sale'?'sale':'purchase';history.pushState({view:type,activityFilter:'all'},'',`#${type}`)},true);
